(function(root){
'use strict';
class NavalAudio{
 constructor(settings={}){this.settings={master:.65,music:.30,effects:.75,mute:false,...settings};this.ctx=null;this.step=0;this.nextNote=0;this.intensity=0;this.playing=false;}
 unlock(){try{if(!this.ctx){this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.music=this.ctx.createGain();this.fx=this.ctx.createGain();this.ambient=this.ctx.createGain();this.master.connect(this.ctx.destination);this.music.connect(this.master);this.fx.connect(this.master);this.ambient.connect(this.master);this.noiseBuffer=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate);const d=this.noiseBuffer.getChannelData(0);let n=0;for(let i=0;i<d.length;i++){n=.985*n+.015*(Math.random()*2-1);d[i]=n*8;}const sea=this.ctx.createBufferSource();sea.buffer=this.noiseBuffer;sea.loop=true;const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=480;sea.connect(filter);filter.connect(this.ambient);sea.start();this.hum=this.ctx.createOscillator();this.hum.type='sawtooth';this.hum.frequency.value=38;this.humGain=this.ctx.createGain();this.humGain.gain.value=.025;this.hum.connect(this.humGain);this.humGain.connect(this.fx);this.hum.start();this.nextNote=this.ctx.currentTime+.1;this.apply();}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}catch(e){this.unavailable=true;}}
 apply(){if(!this.ctx)return;const t=this.ctx.currentTime,s=this.settings;this.master.gain.setTargetAtTime(s.mute?0:s.master,t,.05);this.music.gain.setTargetAtTime(s.music*.24,t,.08);this.fx.gain.setTargetAtTime(s.effects*.34,t,.05);this.ambient.gain.setTargetAtTime(s.effects*.14,t,.1);}
 tone(freq,duration=.15,type='sine',gain=.25,bus=null,when=null,end=null){if(!this.ctx||this.ctx.state!=='running')return;const t=when??this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(end)o.frequency.exponentialRampToValueAtTime(Math.max(12,end),t+duration);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(Math.max(.002,gain),t+.015);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(bus||this.fx);o.start(t);o.stop(t+duration+.05);}
 noise(duration=.4,gain=.6,frequency=900,when=null,bus=null){if(!this.ctx||this.ctx.state!=='running')return;const t=when??this.ctx.currentTime,src=this.ctx.createBufferSource(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();src.buffer=this.noiseBuffer;f.type='lowpass';f.frequency.value=frequency;g.gain.setValueAtTime(gain,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);src.connect(f);f.connect(g);g.connect(bus||this.fx);src.start(t,Math.random(),Math.min(duration,1));}
 effect(type,kind){if(!this.ctx)return;if(type==='fire'){if(kind==='shell'){this.noise(.55,.95,1300);this.tone(110,.38,'triangle',.8,null,null,30);}else if(kind==='missile'){this.noise(.85,.6,2700);this.tone(190,.5,'sawtooth',.12,null,null,500);}else if(kind==='torpedo'){this.tone(70,.65,'sine',.6,null,null,30);this.noise(.45,.25,450);}else this.tone(210,.3,'sawtooth',.15,null,null,80);}if(type==='hit'){this.noise(.7,1,1100);this.tone(55,.6,'triangle',.5);}if(type==='sunk'){this.noise(1,1.6,1300);this.tone(80,1.4,'triangle',.7,null,null,18);}if(type==='scan'){this.tone(780,.85,'sine',.28,null,null,480);}if(type==='intercept')this.noise(.15,.35,3500);if(type==='drone'||type==='jump'){this.tone(410,.65,'sawtooth',.2,null,null,160);}if(type==='land')this.noise(.9,.8,500);if(type==='lock')this.tone(1150,.09,'sine',.24);if(type==='click')this.tone(550,.045,'sine',.12);if(type==='domeDown'){this.tone(170,1.4,'triangle',.5,null,null,620);}}
 update(state,ship){if(!this.ctx||this.ctx.state!=='running')return;const c=this.ctx,t=c.currentTime;this.playing=!!state?.running;this.intensity=Math.min(1,(state?.projectiles?.length||0)/13+(ship&&ship.hp<ship.maxHP*.4?.4:0));this.hum.frequency.setTargetAtTime(36+Math.abs(ship?.velocity||0)*28,t,.3);this.humGain.gain.setTargetAtTime(this.playing?.02+Math.abs(ship?.velocity||0)*.015:.004,t,.2);
  if(this.nextNote<t-.2)this.nextNote=t+.03;while(this.nextNote<t+.12){const beat=this.step%16,bar=Math.floor(this.step/16)%4,base=[65.406,77.782,58.270,51.913][bar],nt=this.nextNote,bus=this.music,active=this.playing;
   if(beat===0){this.tone(base*2,2.2,'triangle',.11,bus,nt);this.tone(base*3,2.2,'sine',.07,bus,nt);this.tone(base*4,2.2,'sine',.04,bus,nt);}
   if(active){if(beat%4===0)this.tone(85,.16,'sine',.45,bus,nt,32);if(beat%4===2)this.noise(.12,.10+this.intensity*.10,1800,nt,bus);if(beat%2===0)this.tone(base*(beat%8===0?1:2),.16,'triangle',.13,bus,nt);if(this.intensity>.4)this.noise(.05,.045,5000,nt,bus);}
   this.step++;this.nextNote+=active?.18:.30;
  }
 }
}
root.IronTideAudio=NavalAudio;
})(window);
